"""Executable boundary: arguments, JSON lines, output, and exit status."""

import argparse
import json
import sys
from collections.abc import Iterable
from typing import Any, TextIO

from .errors import COMPILE_ERROR, RUNTIME_ERROR, CompileError, RuntimeErrorJq
from .evaluator import evaluate
from .parser import parse


def _read_inputs(stream: TextIO) -> Iterable[Any]:
    for line in stream:
        if line.strip():
            try:
                yield json.loads(line)
            except json.JSONDecodeError as error:
                raise RuntimeErrorJq("invalid JSON input") from error


def run(arguments: list[str], stdin: TextIO, stdout: TextIO, stderr: TextIO) -> int:
    """Run one CLI invocation and return the documented process status."""

    parser = argparse.ArgumentParser(prog="jq", add_help=False)
    parser.add_argument("-c", action="store_true")
    parser.add_argument("program", nargs="?")
    options = parser.parse_args(arguments)
    if not options.c or options.program is None:
        stderr.write("usage: jq -c PROGRAM\n")
        return COMPILE_ERROR
    try:
        program = parse(options.program)
    except CompileError as error:
        stderr.write(f"compile error: {error}\n")
        return COMPILE_ERROR
    try:
        for input_value in _read_inputs(stdin):
            for output_value in evaluate(program, input_value):
                stdout.write(json.dumps(output_value, separators=(",", ":")) + "\n")
    except RuntimeErrorJq as error:
        stderr.write(f"runtime error: {error}\n")
        return RUNTIME_ERROR
    return 0


def main() -> None:
    raise SystemExit(run(sys.argv[1:], sys.stdin, sys.stdout, sys.stderr))
"""Parser boundary producing an immutable AST."""

import json

from .ast import Comma, Filter, Identity, Literal, Pipeline
from .errors import CompileError
from .lexer import Token, tokenize


class Parser:
    """Precedence-aware parser for the foundation grammar."""

    def __init__(self, tokens: list[Token]) -> None:
        self._tokens = tokens
        self._position = 0

    def parse(self) -> Filter:
        result = self._parse_comma()
        if self._peek().kind != "EOF":
            raise CompileError("unexpected token")
        return result

    def _parse_comma(self) -> Filter:
        result = self._parse_pipeline()
        while self._accept("COMMA"):
            result = Comma(result, self._parse_pipeline())
        return result

    def _parse_pipeline(self) -> Filter:
        result = self._parse_atom()
        while self._accept("PIPE"):
            result = Pipeline(result, self._parse_atom())
        return result

    def _parse_atom(self) -> Filter:
        token = self._peek()
        if self._accept("DOT"):
            return Identity()
        if token.kind in {"STRING", "NUMBER", "ATOM"}:
            self._position += 1
            try:
                return Literal(json.loads(token.value))
            except json.JSONDecodeError as error:
                raise CompileError("invalid literal") from error
        if self._accept("LPAREN"):
            result = self._parse_comma()
            if not self._accept("RPAREN"):
                raise CompileError("missing closing parenthesis")
            return result
        raise CompileError("expected filter")

    def _peek(self) -> Token:
        return self._tokens[self._position]

    def _accept(self, kind: str) -> bool:
        if self._peek().kind == kind:
            self._position += 1
            return True
        return False


def parse(source: str) -> Filter:
    """Compile source text into an AST or raise :class:`CompileError`."""

    return Parser(tokenize(source)).parse()
